<?php declare(strict_types=1);final class TaskInputValidator{public function publicId($v):string{$v=trim((string)$v);if(!TaskPublicId::isValid($v))throw new TaskValidationException('public_id_invalid');return$v;}public function requiredString(array$d,string$k,int$max):string{$v=trim((string)($d[$k]??''));if($v===''||mb_strlen($v)>$max)throw new TaskValidationException($k.'_invalid');return$v;}public function positiveInt(array$d,string$k,bool$optional=false):?int{if($optional&&(!isset($d[$k])||$d[$k]===''))return null;$v=filter_var($d[$k]??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($v===false)throw new TaskValidationException($k.'_invalid');return(int)$v;}public function lock(array$d):int{$v=filter_var($d['lock_version']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);if($v===false)throw new TaskValidationException('lock_version_invalid');return(int)$v;}public function oneOf($v,array$a,string$error):string{$v=(string)$v;if(!in_array($v,$a,true))throw new TaskValidationException($error);return$v;}}
